"""Core MLIR-style IR data structures.

A minimal subset of MLIR: contexts, dialect registry, types, values,
operations, blocks, regions and modules. Operations support pre-order
``walk`` traversal, use replacement and erasure, which is what the
rewrite machinery in ``pattern.py`` and the passes in
``pass_manager.py`` build upon.
"""


# ---------------------------------------------------------------------------
# Context and dialects
# ---------------------------------------------------------------------------

class Dialect:
    """A registered dialect: a namespace plus the op names it defines."""

    def __init__(self, name, op_names=()):
        self.name = name
        self.op_names = set(op_names)


class MLIRContext:
    """Holds loaded dialects. Types are structural, so no interning needed."""

    def __init__(self):
        self.dialects = {}

    def register_dialect(self, dialect):
        self.dialects[dialect.name] = dialect
        return dialect

    def get_dialect(self, name):
        return self.dialects.get(name)


# ---------------------------------------------------------------------------
# Types
# ---------------------------------------------------------------------------

class Type:
    def __str__(self):  # pragma: no cover - overridden
        raise NotImplementedError

    def __repr__(self):
        return str(self)


class IntegerType(Type):
    """Signless integer type, e.g. ``i32``."""

    def __init__(self, width):
        self.width = int(width)

    def __str__(self):
        return f"i{self.width}"

    def __eq__(self, other):
        return isinstance(other, IntegerType) and other.width == self.width

    def __hash__(self):
        return hash(("i", self.width))


class OpaqueType(Type):
    """A dialect type kept in unparsed form, e.g. ``!seq.clock``."""

    def __init__(self, dialect, data):
        self.dialect = dialect
        self.data = data

    def __str__(self):
        return f"!{self.dialect}.{self.data}"

    def __eq__(self, other):
        return (isinstance(other, OpaqueType)
                and other.dialect == self.dialect and other.data == self.data)

    def __hash__(self):
        return hash(("!", self.dialect, self.data))


def type_from_string(text):
    """Build a Type from its textual form (``i32`` or ``!seq.clock``)."""
    text = text.strip()
    if text.startswith("i") and text[1:].isdigit():
        return IntegerType(int(text[1:]))
    if text.startswith("!"):
        body = text[1:]
        dialect, _, data = body.partition(".")
        return OpaqueType(dialect, data)
    return OpaqueType("builtin", text)


# ---------------------------------------------------------------------------
# Values
# ---------------------------------------------------------------------------

class Value:
    """An SSA value: either an OpResult or a BlockArgument.

    ``uses`` is a list of ``[operation, operand_index]`` pairs, kept up to
    date as operands are rewired.
    """

    def __init__(self, type=None, name=""):
        self.type = type
        self.name = name
        self.uses = []

    def replace_all_uses_with(self, new_value):
        for op, index in list(self.uses):
            op.set_operand(index, new_value)

    def __repr__(self):
        return f"{self.__class__.__name__}({self.name}: {self.type})"


class OpResult(Value):
    def __init__(self, owner, index, type=None, name=""):
        super().__init__(type, name)
        self.owner = owner
        self.index = index


class BlockArgument(Value):
    def __init__(self, block, index, type=None, name=""):
        super().__init__(type, name)
        self.block = block
        self.index = index


# ---------------------------------------------------------------------------
# Operations / Blocks / Regions
# ---------------------------------------------------------------------------

class Operation:
    """A generic operation.

    Attributes is a plain dict; the parser stores, among others:
    ``value`` (int constant payload), ``predicate`` (cmpi/icmp),
    ``types`` (the trailing colon type list, as strings),
    ``sym_name`` / ``args`` / ``result_type`` (func.func),
    ``ports`` (hw.module).
    """

    def __init__(self, name, operands=(), result_types=(), attributes=None,
                 successors=()):
        self.name = name
        self.operands = []
        self.results = [OpResult(self, i, t) for i, t in enumerate(result_types)]
        self.attributes = dict(attributes or {})
        self.regions = []
        self.successors = []
        self.parent = None  # owning Block
        for value in operands:
            self.add_operand(value)
        for block in successors:
            self.successors.append(block)

    # -- operands / uses ----------------------------------------------------

    def add_operand(self, value):
        value.uses.append([self, len(self.operands)])
        self.operands.append(value)

    def set_operand(self, index, new_value):
        old = self.operands[index]
        old.uses = [u for u in old.uses
                    if not (u[0] is self and u[1] == index)]
        self.operands[index] = new_value
        new_value.uses.append([self, index])

    # -- structure ----------------------------------------------------------

    def add_region(self, region=None):
        region = region or Region()
        region.parent = self
        self.regions.append(region)
        return region

    # -- traversal ----------------------------------------------------------

    def walk(self, fn):
        """Pre-order traversal: fn(self), then all nested ops."""
        fn(self)
        for region in self.regions:
            for block in region.blocks:
                for op in list(block.ops):
                    op.walk(fn)

    # -- mutation -----------------------------------------------------------

    def erase(self):
        """Detach from the parent block and drop this op's operand uses."""
        for value in self.operands:
            value.uses = [u for u in value.uses if u[0] is not self]
        self.operands = []
        if self.parent is not None:
            self.parent.ops.remove(self)
            self.parent = None

    def replace_all_uses_with(self, other):
        """Replace uses of this op's results with another op's results."""
        for old, new in zip(self.results, other.results):
            old.replace_all_uses_with(new)

    def __repr__(self):
        return f"Operation({self.name})"


class Block:
    def __init__(self, name=None):
        self.name = name  # block label without '^', or None for entry blocks
        self.args = []
        self.ops = []
        self.region = None  # owning Region

    def add_argument(self, type=None, name=""):
        arg = BlockArgument(self, len(self.args), type, name)
        self.args.append(arg)
        return arg

    def add_op(self, op):
        op.parent = self
        self.ops.append(op)
        return op

    def insert_op_before(self, ref_op, op):
        index = self.ops.index(ref_op)
        op.parent = self
        self.ops.insert(index, op)
        return op

    def __repr__(self):
        return f"Block(^{self.name})" if self.name else "Block(<entry>)"


class Region:
    def __init__(self, blocks=()):
        self.blocks = []
        self.parent = None  # owning Operation
        for block in blocks:
            self.add_block(block)

    def add_block(self, block=None):
        block = block or Block()
        block.region = self
        self.blocks.append(block)
        return block


class Module(Operation):
    """Top-level ``builtin.module`` op with a single region and block."""

    def __init__(self, context=None):
        super().__init__("builtin.module")
        self.context = context or MLIRContext()
        body_region = self.add_region()
        body_region.add_block()

    @property
    def body(self):
        return self.regions[0].blocks[0]

    @property
    def ops(self):
        return self.body.ops

"""A pragmatic text parser for a subset of MLIR.

Parses ``module { ... }`` containing ``func.func`` and ``hw.module``
ops, basic blocks with ``^label:`` headers, and generic op lines of the
form ``%r = dialect.op <operands/successors/keywords> : <types>``.

SSA operand names may be forward references (e.g. ``seq.compreg`` uses
``%next`` before it is defined); they are resolved once the whole module
has been read. Block successors are resolved per enclosing region.
"""

import re

from .ir import (
    Module,
    Operation,
    Region,
    type_from_string,
)

_FUNC_HEADER = re.compile(
    r"^func\.func\s+@(?P<name>[\w.$]+)\s*\((?P<args>[^)]*)\)"
    r"\s*(?:->\s*(?P<ret>[^\s{]+))?\s*\{$")

_HW_MODULE_HEADER = re.compile(
    r"^hw\.module\s+@(?P<name>[\w.$]+)\s*\((?P<ports>[^)]*)\)\s*\{$")

_BLOCK_LABEL = re.compile(r"^\^(?P<label>[\w.$]+):$")

_RESULTS_PREFIX = re.compile(
    r"^(?P<results>%[\w.$]+(?:\s*,\s*%[\w.$]+)*)\s*=\s*(?P<rest>.*)$")

_TOKEN = re.compile(
    r"->|%[\w.$]+|\^[\w.$]+|@[\w.$]+|![\w.$]+|[A-Za-z_][\w.$]*|-?\d+"
    r"|[{}():,=]")

_PORT = re.compile(r"^(?P<dir>in|out)\s+%?(?P<name>[\w.$]+)\s*:\s*(?P<type>.+)$")

_ARG = re.compile(r"^(?P<name>%[\w.$]+)\s*:\s*(?P<type>.+)$")


def parse(source, context=None):
    """Parse MLIR text and return a ``Module``."""
    lines = []
    for raw in source.split("\n"):
        line = raw.split("//", 1)[0].strip()
        if line:
            lines.append(line)
    parser = _Parser(lines, context)
    return parser.parse_module()


class _Parser:
    def __init__(self, lines, context):
        self.lines = lines
        self.pos = 0
        self.module = Module(context)
        self.symbols = {}      # SSA name (with '%') -> Value
        self.value_fixups = []  # (op, [operand names])
        self.block_stack = []   # per function-like op: (op, label_map, succ fixups)

    # -- helpers -------------------------------------------------------------

    def peek(self):
        return self.lines[self.pos] if self.pos < len(self.lines) else None

    def next(self):
        line = self.lines[self.pos]
        self.pos += 1
        return line

    def error(self, msg):
        raise ValueError(f"parse error at line {self.pos + 1}: {msg}: "
                         f"{self.lines[self.pos]!r}" if self.pos < len(self.lines)
                         else f"parse error at end of input: {msg}")

    # -- top level -----------------------------------------------------------

    def parse_module(self):
        if self.next() != "module {":
            self.error("expected 'module {'")
        body = self.module.body
        while True:
            line = self.peek()
            if line is None:
                self.error("unterminated module")
            if line == "}":
                self.next()
                break
            self.parse_op_line(line, body)
            self.pos += 1
        self.resolve_values()
        return self.module

    def resolve_values(self):
        for op, names in self.value_fixups:
            for name in names:
                value = self.symbols.get(name)
                if value is None:
                    raise ValueError(f"undefined SSA value {name!r} "
                                     f"used by op {op.name!r}")
                op.add_operand(value)

    # -- function-like ops ---------------------------------------------------

    def parse_op_line(self, line, block):
        m = _FUNC_HEADER.match(line)
        if m:
            self.parse_func(m, block)
            return
        m = _HW_MODULE_HEADER.match(line)
        if m:
            self.parse_hw_module(m, block)
            return
        op = self.parse_generic_op(line)
        block.add_op(op)

    def parse_func(self, m, parent_block):
        args = []
        arg_text = m.group("args").strip()
        if arg_text:
            for piece in arg_text.split(","):
                am = _ARG.match(piece.strip())
                if not am:
                    raise ValueError(f"bad func argument: {piece!r}")
                args.append((am.group("name"), am.group("type").strip()))
        attributes = {
            "sym_name": m.group("name"),
            "args": args,
        }
        if m.group("ret"):
            attributes["result_type"] = m.group("ret")
        op = Operation("func.func", attributes=attributes)
        parent_block.add_op(op)
        self.parse_body(op, entry_args=args)

    def parse_hw_module(self, m, parent_block):
        ports = []
        port_text = m.group("ports").strip()
        if port_text:
            for piece in port_text.split(","):
                pm = _PORT.match(piece.strip())
                if not pm:
                    raise ValueError(f"bad hw.module port: {piece!r}")
                ports.append({
                    "dir": pm.group("dir"),
                    "name": pm.group("name"),
                    "type": pm.group("type").strip(),
                })
        op = Operation("hw.module", attributes={
            "sym_name": m.group("name"),
            "ports": ports,
        })
        parent_block.add_op(op)
        entry_args = [("%" + p["name"], p["type"]) for p in ports
                      if p["dir"] == "in"]
        self.parse_body(op, entry_args=entry_args)

    def parse_body(self, op, entry_args):
        """Parse ``^label:`` blocks and op lines until the closing brace."""
        region = op.add_region(Region())
        label_map = {}
        succ_fixups = []  # (op, [label names])
        entry = region.add_block()
        for name, type_text in entry_args:
            arg = entry.add_argument(type_from_string(type_text), name)
            self.symbols[name] = arg
        current = entry
        while True:
            line = self.peek()
            if line is None:
                raise ValueError(f"unterminated body of {op.name!r}")
            if line == "}":
                self.next()
                break
            self.next()
            lm = _BLOCK_LABEL.match(line)
            if lm:
                block = region.add_block()
                block.name = lm.group("label")
                label_map[block.name] = block
                current = block
            else:
                parsed = self.parse_generic_op(line)
                current.add_op(parsed)
                if parsed._successor_labels:
                    succ_fixups.append(parsed)
        for parsed in succ_fixups:
            for label in parsed._successor_labels:
                target = label_map.get(label)
                if target is None:
                    raise ValueError(f"undefined block label ^{label!r} "
                                     f"used by op {parsed.name!r}")
                parsed.successors.append(target)
            del parsed._successor_labels

    # -- generic ops ----------------------------------------------------------

    def parse_generic_op(self, line):
        result_names = []
        m = _RESULTS_PREFIX.match(line)
        if m:
            result_names = [r.strip() for r in m.group("results").split(",")]
            rest = m.group("rest")
        else:
            rest = line
        tokens = _TOKEN.findall(rest)
        if not tokens:
            raise ValueError(f"cannot parse op line: {line!r}")
        name = tokens[0]

        operand_names = []
        successor_labels = []
        attributes = {}
        keywords = []
        types = []
        i = 1
        while i < len(tokens):
            tok = tokens[i]
            if tok == ":":
                types = [t for t in tokens[i + 1:]
                         if t not in (",", "(", ")") and t != "->"]
                break
            if tok.startswith("%"):
                operand_names.append(tok)
            elif tok.startswith("^"):
                successor_labels.append(tok[1:])
            elif tok.startswith("-" ) or tok.isdigit():
                attributes["value"] = int(tok)
            elif tok == "reset":
                attributes["reset"] = True
            elif name in ("arith.cmpi", "comb.icmp") and "predicate" not in attributes:
                attributes["predicate"] = tok
            elif tok != ",":
                keywords.append(tok)
            i += 1
        if keywords:
            attributes["keywords"] = keywords
        if types:
            attributes["types"] = types

        result_types = []
        if result_names and types:
            result_types = [type_from_string(types[0])
                            for _ in result_names]
        op = Operation(name, result_types=result_types,
                       attributes=attributes)
        for result, result_name in zip(op.results, result_names):
            result.name = result_name
            self.symbols[result_name] = result
        op._successor_labels = successor_labels
        if operand_names:
            self.value_fixups.append((op, operand_names))
        return op

