"""Render a Module back to MLIR-like text.

The output is re-parseable by ``parser.parse``:
``parse(print_module(parse(src)))`` yields an equivalent module.
"""

_INDENT = "  "


def print_module(module):
    """Return the textual form of ``module`` (ends with a newline)."""
    lines = ["module {"]
    for op in module.body.ops:
        _print_op(op, 1, lines)
    lines.append("}")
    return "\n".join(lines) + "\n"


def _print_op(op, level, lines):
    pad = _INDENT * level
    if op.name == "func.func":
        args = op.attributes.get("args", [])
        arg_str = ", ".join(f"{name}: {typ}" for name, typ in args)
        header = f"{pad}func.func @{op.attributes['sym_name']}({arg_str})"
        if op.attributes.get("result_type"):
            header += f" -> {op.attributes['result_type']}"
        lines.append(header + " {")
        _print_region(op.regions[0], level + 1, lines)
        lines.append(pad + "}")
    elif op.name == "hw.module":
        ports = op.attributes.get("ports", [])
        port_str = ", ".join(_format_port(p) for p in ports)
        lines.append(
            f"{pad}hw.module @{op.attributes['sym_name']}({port_str}) {{")
        _print_region(op.regions[0], level + 1, lines)
        lines.append(pad + "}")
    else:
        lines.append(pad + _format_op(op))


def _format_port(port):
    if port["dir"] == "in":
        return f"in %{port['name']}: {port['type']}"
    return f"out {port['name']}: {port['type']}"


def _print_region(region, level, lines):
    pad = _INDENT * level
    for i, block in enumerate(region.blocks):
        if block.name is not None or i > 0:
            label = block.name if block.name is not None else f"bb{i}"
            lines.append(f"{pad}^{label}:")
        for op in block.ops:
            _print_op(op, level, lines)


def _format_op(op):
    parts = []
    if op.results:
        parts.append(", ".join(r.name for r in op.results) + " =")
    parts.append(op.name)

    if "value" in op.attributes and not op.operands:
        tail = str(op.attributes["value"])
    elif op.name == "seq.compreg" and op.attributes.get("reset"):
        head = ", ".join(v.name for v in op.operands[:2])
        rest = ", ".join(v.name for v in op.operands[2:])
        tail = f"{head} reset {rest}"
    else:
        items = []
        if "predicate" in op.attributes:
            items.append(op.attributes["predicate"])
        items.extend(v.name for v in op.operands)
        items.extend(op.attributes.get("keywords", []))
        items.extend("^" + b.name for b in op.successors)
        tail = ", ".join(items)

    text = " ".join(parts)
    if tail:
        text += " " + tail
    types = op.attributes.get("types", [])
    if types:
        text += " : " + ", ".join(types)
    return text

"""Rewrite pattern machinery.

``RewritePattern`` subclasses implement ``match_and_rewrite``; a
``PatternRewriter`` performs the actual IR mutations (op replacement,
erasure). ``apply_patterns_greedily`` walks a root op and applies the
patterns until a fixpoint is reached.
"""

from .ir import Operation


class PatternRewriter:
    """Mutates the IR on behalf of patterns and tracks whether it did."""

    def __init__(self):
        self.changed = False

    def insert_op_before(self, ref_op, new_op):
        if ref_op.parent is None:
            raise ValueError("reference op is not attached to a block")
        ref_op.parent.insert_op_before(ref_op, new_op)
        self.changed = True
        return new_op

    def replace_op(self, op, new_op):
        """Insert ``new_op`` before ``op``, forward result uses, erase ``op``."""
        self.insert_op_before(op, new_op)
        op.replace_all_uses_with(new_op)
        op.erase()

    def erase_op(self, op):
        op.erase()
        self.changed = True


class RewritePattern:
    """Base class: return True (and mutate via the rewriter) on a match."""

    def match_and_rewrite(self, op, rewriter):
        raise NotImplementedError


def apply_patterns_greedily(root, patterns, max_iterations=1000):
    """Apply ``patterns`` over ``root`` (inclusive) until fixpoint.

    Returns True if any pattern fired.
    """
    rewriter = PatternRewriter()
    any_change = False
    for _ in range(max_iterations):
        rewriter.changed = False
        ops = []
        root.walk(ops.append)
        for op in ops:
            if op.parent is None and op is not root:
                continue  # erased earlier in this iteration
            for pattern in patterns:
                if pattern.match_and_rewrite(op, rewriter):
                    break
        if not rewriter.changed:
            return any_change
        any_change = True
    raise RuntimeError("greedy pattern application did not converge")

"""Pass infrastructure: PassManager and the ConstantFolding pass."""

from . import ir
from .dialects import arith
from .pattern import PatternRewriter, RewritePattern, apply_patterns_greedily


class Pass:
    """Base class for passes. Keeps named integer statistics."""

    name = "pass"

    def __init__(self):
        self.statistics = {}

    def get_statistic(self, key, default=0):
        return self.statistics.get(key, default)

    def run(self, module):
        raise NotImplementedError


class PassManager:
    def __init__(self):
        self.passes = []

    def add_pass(self, p):
        self.passes.append(p)
        return p

    def run(self, module):
        for p in self.passes:
            p.run(module)
        return module


class _ConstantFoldPattern(RewritePattern):
    """Folds one foldable arith op whose operands are all constants."""

    def __init__(self, statistics):
        self.statistics = statistics
        self.counter = 0

    def match_and_rewrite(self, op, rewriter):
        if op.name not in arith.FOLDABLE_OPS:
            return False
        if not op.operands:
            return False
        values = []
        for operand in op.operands:
            owner = getattr(operand, "owner", None)
            if owner is None or owner.name != "arith.constant":
                return False
            if "value" not in owner.attributes:
                return False
            values.append(owner.attributes["value"])
        folded = arith.fold_operation(op.name, op.attributes, values)
        if folded is None:
            return False

        result_type = op.results[0].type if op.results else None
        type_text = str(result_type) if result_type is not None else "i32"
        constant = ir.Operation(
            "arith.constant",
            result_types=[result_type],
            attributes={"value": folded, "types": [type_text]},
        )
        constant.results[0].name = f"%fold{self.counter}"
        self.counter += 1
        rewriter.replace_op(op, constant)
        self.statistics["num_folded"] = self.statistics.get("num_folded", 0) + 1
        return True


class ConstantFolding(Pass):
    """Folds arith ops on constant operands, iterating to a fixpoint."""

    name = "constant-folding"

    def run(self, module):
        pattern = _ConstantFoldPattern(self.statistics)
        apply_patterns_greedily(module, [pattern])

