def parse_module(self):
    body = self.module.body
    # Accept both an explicit `module { ... }` wrapper and bare
    # top-level ops (e.g. a standalone hw.module).
    wrapped = self.peek() == "module {"
    if wrapped:
        self.next()
    while True:
        line = self.peek()
        if line is None:
            if wrapped:
                self.error("unterminated module")
            break
        if line == "}":
            if not wrapped:
                self.error("unexpected '}'")
            self.next()
            break
        # Consume the line here; function-like headers hand off to
        # parse_body, which continues reading from self.pos.
        self.parse_op_line(self.next(), body)

